import { Sparkles } from '../icons'
import { useEffect, useRef, useState, type CSSProperties } from 'react'
import { useMemory } from '../state/MemoryContext'
import styles from './HomePage.module.css'

const rings = [
  ['여백 많은 UI', '속도 우선', '디카페인', '290mm', '다크 모드'],
  ['Swift 재도입', '해커톤 몰입', 'B2B 탐색', 'MVP 이틀', '파스텔 거부', 'M2 Air', '협업 SaaS'],
  ['AI 코딩 도구', '완성도 타협 안 함', '정보 밀도 낮게', '프로젝트 3.4개', 'Flutter 감소', '휴학 고민', 'B2C 창업', '근거 14개'],
]

type AnswerPhase = 'idle' | 'searching' | 'revealed'

export function HomePage() {
  const { workspace } = useMemory()
  const [activeQuestion, setActiveQuestion] = useState(0)
  const [phase, setPhase] = useState<AnswerPhase>('idle')
  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const selected = workspace.orbitQuestions[activeQuestion]

  useEffect(() => () => {
    if (searchTimer.current) clearTimeout(searchTimer.current)
  }, [])

  const selectQuestion = (index: number) => {
    if (searchTimer.current) clearTimeout(searchTimer.current)

    setActiveQuestion(index)
    setPhase('searching')
    searchTimer.current = setTimeout(() => {
      setPhase('revealed')
      searchTimer.current = null
    }, 1050)
  }

  return (
    <section className={styles.page} aria-labelledby="orbit-title">
      <header className={styles.header}>
        <div><span className={styles.eyebrow}>YOUR MEMORY · {workspace.memoryCount}</span><h1 id="orbit-title">지금 당신은 이렇게 생겼습니다</h1></div>
        <div className={styles.week}>이번 주 기억 변화 <b>{workspace.week.strengthened + workspace.week.archived + workspace.week.merged}</b><span>· 판단 {workspace.week.pending}</span></div>
      </header>

      <div className={styles.orbitStage} data-phase={phase} data-testid="orbit-stage">
        <div className={`${styles.ambient} visual-blur`} />
        <div className={`${styles.grain} visual-extra`} />
        {rings.map((words, ringIndex) => (
          <div key={ringIndex} className={`${styles.ring} ${styles[`ring${ringIndex + 1}`]}`}>
            <div className={styles.ringLine} />
            {words.map((word, index) => {
              const angle = (360 / words.length) * index
              return <span key={word} style={{ '--angle': `${angle}deg` } as CSSProperties}>{word}</span>
            })}
          </div>
        ))}
        <div className={styles.coreGlow} />
        <div className={styles.core}><Sparkles size={16} /><span>MEMORY OS</span></div>
        {phase !== 'revealed' ? (
          <div className={styles.answer} aria-live="polite"><p>{selected.answer}</p><span>{selected.meta}</span></div>
        ) : (
          <ul className={styles.answerCards} aria-label="질문 결과" aria-live="polite">
            {selected.answerCards.map((card) => <li key={card} className={styles.answerCard}>{card}</li>)}
          </ul>
        )}
        <span className={`${styles.pulse} ${styles.pulseOne} visual-extra`}>새 기억 · Swift 프로젝트 시작</span>
        <span className={`${styles.pulse} ${styles.pulseTwo} visual-extra`}>강화됨 · 여백 선호 +19</span>
      </div>

      <div className={styles.composerArea}>
        <div className={styles.chips}>
          {workspace.orbitQuestions.map((item, index) => <button key={item.id} aria-pressed={index === activeQuestion} onClick={() => selectQuestion(index)}>{item.question}</button>)}
        </div>
      </div>
    </section>
  )
}

import { ArrowRight, Check, Clock3, X } from '../icons'
import { useState } from 'react'
import { useLocation } from 'react-router-dom'
import type { MemoryChange } from '../domain/memory'
import { useMemory } from '../state/MemoryContext'
import screen from './Screen.module.css'
import styles from './ChangesPage.module.css'

const kindLabel: Record<MemoryChange['kind'], string> = {
  changed: 'CHANGED', fading: 'FADING', duplicate: 'DUPLICATE', contradiction: 'CONTRADICTION',
}

const weeks = ['8월 10일 — 8월 16일', '8월 3일 — 8월 9일', '7월 27일 — 8월 2일', '7월 20일 — 7월 26일']

export function ChangesPage() {
  const { workspace, resolveChange } = useMemory()
  const location = useLocation()
  const [modal, setModal] = useState<'diff' | 'review' | 'cleanup' | null>(() => (location.state as { openCleanup?: boolean } | null)?.openCleanup ? 'cleanup' : null)
  const [cleanupIndex, setCleanupIndex] = useState(0)
  const [showAll, setShowAll] = useState(false)
  const [showEvidence, setShowEvidence] = useState(false)
  const [selectedWeek, setSelectedWeek] = useState(weeks[0])
  const [weekPickerOpen, setWeekPickerOpen] = useState(false)
  const pending = workspace.changes.filter((item) => item.status === 'pending')
  const change = workspace.changes[0]
  const cleanup = workspace.memories.filter((item) => item.state === 'fading' || item.state === 'review').slice(0, 3)

  const advanceCleanup = () => {
    if (cleanupIndex >= cleanup.length - 1) { setModal(null); setCleanupIndex(0) }
    else setCleanupIndex((value) => value + 1)
  }

  return (
    <section className={screen.screen}>
      <div className={screen.inner}>
        <div className={screen.topRow}>
          <header>
            <div className={styles.weekControl}>
              <button
                className={screen.datePicker}
                aria-expanded={weekPickerOpen}
                aria-haspopup="listbox"
                aria-controls="changes-week-picker"
                onClick={() => setWeekPickerOpen((value) => !value)}
              >
                {selectedWeek}
              </button>
              {weekPickerOpen && <div id="changes-week-picker" className={styles.weekPicker} role="listbox" aria-label="Changes 기간">
                {weeks.map((week) => <button
                  key={week}
                  role="option"
                  aria-selected={week === selectedWeek}
                  onClick={() => { setSelectedWeek(week); setWeekPickerOpen(false) }}
                >
                  {week}
                </button>)}
              </div>}
            </div>
            <h1 className={screen.heading}>이번 주, AI가 당신에 대해 이해한 것이<br />이렇게 달라졌습니다.</h1>
          </header>
          <button className={screen.buttonGhost} onClick={() => setModal('cleanup')}><Clock3 size={14} />47초 정리</button>
        </div>

        <div className={styles.summaryBar}>
          <div><span>이번 주 Memory OS가 대부분을 정리했습니다.</span><strong>전체 {workspace.memoryCount}개 중 94% 자동 정리 · 직접 판단 {pending.length}건</strong></div>
          <button className={screen.buttonGhost} onClick={() => setModal('review')}>빠르게 판단하기 <ArrowRight size={14} /></button>
        </div>

        <div className={styles.sectionHead}><span>가장 중요한 변화</span><b>1건</b><div /></div>
        <div className={styles.feed} id="changes-feed">
          {(showAll ? workspace.changes : workspace.changes.slice(0, 1)).map((item) => (
            <article key={item.id} className={`${styles.changeCard} ${item.status === 'resolved' ? styles.resolved : ''}`}>
              {item.id !== 'flutter-change' && <div className={styles.cardMeta}><span>{kindLabel[item.kind]}</span><small>{item.meta}</small></div>}
              <h2>{item.id === 'flutter-change' ? 'Flutter를 선호하지 않습니다.' : item.title}</h2><p>{item.description}</p>
              {item.evidence.length > 0 && <ul>{item.evidence.slice(0, 2).map((entry) => <li key={entry}>{entry}</li>)}</ul>}
              <div className={styles.cardActions}>
                {item.status === 'resolved' ? <span className={styles.done}><Check size={13} /> 반영됨</span> : <>
                  {item.id === 'flutter-change' ? <>
                    <button className={styles.acceptButton} aria-label="이 변화가 맞음" onClick={() => void resolveChange(item.id, 'accept')}><Check size={18} aria-hidden="true" /></button>
                    <button className={`${screen.buttonGhost} ${styles.detailsButton}`} onClick={() => setModal('diff')}>변경 내용 보기</button>
                  </> : <>
                    <button className={screen.button} onClick={() => void resolveChange(item.id, 'accept')}>{item.kind === 'fading' ? '지금 보관' : item.kind === 'duplicate' ? '하나로 병합' : '조건 저장'}</button>
                    <button className={screen.textButton} onClick={() => void resolveChange(item.id, 'reject')}>아직 유효해요</button>
                  </>}
                </>}
              </div>
            </article>
          ))}
        </div>
        <button className={styles.disclosure} aria-expanded={showAll} aria-controls="changes-feed" onClick={() => setShowAll((value) => !value)}>{showAll ? '간단히 보기' : `나머지 ${workspace.changes.length - 1}개 보기`}<ArrowRight size={14} /></button>
      </div>

      {modal === 'diff' && <div className={styles.backdrop} onMouseDown={() => setModal(null)}><div className={styles.dialog} role="dialog" aria-modal="true" aria-label="이해 업데이트 제안" onMouseDown={(event) => event.stopPropagation()}>
        <div className={styles.dialogTop}><span>이해 업데이트 제안</span><button autoFocus aria-label="닫기" onClick={() => setModal(null)}><X size={16} /></button></div>
        <h2>AI가 당신에 대한 이해를<br />이렇게 바꾸려 합니다.</h2>
        <div className={styles.diff}><div><span>BEFORE</span><p>{change.before}</p></div><ArrowRight size={18} /><div><span>AFTER</span><p>{change.after}</p></div></div>
        <p className={styles.evidence}>근거 {change.evidence.length + 11}개 · 최근 90일 대화에서 수집</p>
        {showEvidence && <ul className={styles.dialogEvidence}>{change.evidence.map((item) => <li key={item}>{item}</li>)}</ul>}
        <div className={styles.dialogActions}><button className={screen.button} onClick={async () => { await resolveChange(change.id, 'accept'); setModal(null) }}>이 이해를 승인</button><button className={screen.buttonGhost} onClick={() => setModal(null)}>기존 유지</button><button className={screen.textButton} aria-expanded={showEvidence} onClick={() => setShowEvidence((value) => !value)}>{showEvidence ? '근거 접기' : '근거 더 보기'}</button></div>
      </div></div>}

      {modal === 'review' && <div className={styles.backdrop} onMouseDown={() => setModal(null)}><div className={`${styles.dialog} ${styles.reviewDialog}`} role="dialog" aria-modal="true" aria-label="판단 필요" onMouseDown={(event) => event.stopPropagation()}>
        <div className={styles.dialogTop}><span>판단 필요 · 1 / 2</span><button autoFocus onClick={() => setModal(null)}>나중에</button></div><h2>창업은 B2C 위주로 하고 싶음</h2><span className={styles.outdated}>아마도 낡은 기억</span><p>8개월 전에 만들어진 기억입니다. 그 이후 B2B 아이디어를 7번 탐색하고 협업 SaaS를 3번 검토했습니다.</p><div className={styles.dialogActions}><button className={screen.button} onClick={() => setModal(null)}>맞아요, 약화시켜요</button><button className={screen.buttonGhost} onClick={() => setModal(null)}>아직 유효해요</button></div>
      </div></div>}

      {modal === 'cleanup' && <div className={styles.cleanupBackdrop} role="dialog" aria-modal="true" aria-label="기억 정리"><div className={styles.cleanupTop}><span>MEMORY CLEANUP</span><b>{cleanupIndex + 1} / {cleanup.length}</b></div><div className={styles.cleanupStack}><i /><i /><div className={styles.cleanupCard}><span>{cleanup[cleanupIndex].category} · {cleanup[cleanupIndex].ageLabel}</span><h2>{cleanup[cleanupIndex].text}</h2><p>최근 답변에 미치는 영향이 낮아졌습니다. 이 기억을 계속 유지할까요?</p><div><button autoFocus className={screen.buttonGhost} onClick={advanceCleanup}>← 잊어도 돼</button><button className={screen.button} onClick={advanceCleanup}>유지 →</button></div></div></div><button className={screen.textButton} onClick={() => setModal(null)}>그만하기 · 나머지는 AI가 알아서</button></div>}
    </section>
  )
}

import { Check, GitBranch, Pin, Sparkles } from '../icons'
import { useState, type CSSProperties } from 'react'
import { NavLink, Navigate, useNavigate, useParams } from 'react-router-dom'
import type { MemoryCategory } from '../domain/memory'
import { useMemory } from '../state/MemoryContext'
import screen from './Screen.module.css'
import styles from './MemoryPage.module.css'
import { getClusterPoint } from './clusterLayout'

const validLenses = ['half-life', 'constellation', 'manual']

export function MemoryPage() {
  const { lens } = useParams()
  if (!lens || !validLenses.includes(lens)) return <Navigate to="/memory/half-life" replace />
  return <section className={screen.screen}><div className={screen.inner}>
    <div className={screen.topRow}><nav className={`${screen.tabs} ${styles.lensTabs}`} aria-label="기억 렌즈"><NavLink to="/memory/half-life">시간 흐름</NavLink><NavLink to="/memory/constellation">기억 관계</NavLink><NavLink to="/memory/manual">사용자 설명</NavLink></nav></div>
    {lens === 'half-life' && <HalfLife />}{lens === 'constellation' && <Constellation />}{lens === 'manual' && <Manual />}
  </div></section>
}

function HalfLife() {
  const { workspace, setPinned } = useMemory()
  const navigate = useNavigate()
  const [kept, setKept] = useState(false)
  const [selectedCategory, setSelectedCategory] = useState<MemoryCategory>('코딩')
  const buckets = ['archive', '1y', '90d', '30d', 'now'] as const
  const labels = ['보관 예정', '1년 전', '90일 전', '30일 전', '최근']
  const categories: MemoryCategory[] = ['코딩', '일', '취향', '개인']
  return <div className={styles.halfLife}>
    <div className={styles.lensHeading}><div><h1>612개 중 어떤 것이 식어가고 있는가</h1><p>기억은 지우는 게 아니라 시간이 지나면 옅어집니다. 붙잡고 싶은 것만 핀을 꽂으세요.</p></div><div className={styles.archiveCount}><b>18</b><span>7일 내 자동 보관 예정</span></div></div>
    <div className={styles.categoryTabs} aria-label="기억 분야">
      {categories.map((category) => <button key={category} type="button" aria-pressed={selectedCategory === category} onClick={() => setSelectedCategory(category)}>{category}</button>)}
    </div>
    <div className={styles.timelineHead}><span />{labels.map((label) => <b key={label}>{label}</b>)}</div>
    <div className={styles.timelineLine} />
    <div className={styles.memoryGrid}>
      <div className={styles.memoryRow}><strong>{selectedCategory}</strong>{buckets.map((bucket) => <div key={bucket} className={styles.bucket}>{workspace.memories.filter((item) => item.category === selectedCategory && item.ageBucket === bucket).map((memory) => <button key={memory.id} className={`${styles.memoryChip} ${styles[memory.state]} ${memory.pinned ? styles.pinned : ''}`} aria-label={`${memory.text} 고정`} aria-pressed={memory.pinned} onClick={() => void setPinned(memory.id, !memory.pinned)} style={{ '--strength': memory.strength } as CSSProperties}><span>{memory.text}</span>{memory.pinned && <Pin size={10} fill="currentColor" />}</button>)}</div>)}</div>
    </div>
    <div className={styles.legend}><span><i className={styles.legendStrong} />핀으로 고정됨 · 식지 않음</span><span><i className={styles.legendFading} />옅어지는 중</span><span><i className={styles.legendArchive} />곧 보관</span>{kept && <span className={styles.resolved}><Check size={13} />18개 유지됨</span>}<div /><button className={screen.button} onClick={() => setKept(true)}>보관 예정 18개 그대로 두기</button><button className={screen.buttonGhost} onClick={() => navigate('/changes', { state: { openCleanup: true } })}>하나씩 보기</button></div>
  </div>
}

function Constellation() {
  const { workspace, resolveTension } = useMemory()
  const tension = workspace.tensions[0]
  return <div className={styles.constellation}>
    <div className={styles.sky}>
      <div className={styles.skyTitle}><h1>당신은 네 개의 덩어리로<br />이루어져 있습니다</h1></div>
      <Cluster className={styles.making} name="MAKING" count="148" words={['속도 우선','AI 코딩 도구','MVP 이틀','해커톤 몰입']} />
      <Cluster className={styles.craft} name="CRAFT" count="96" words={['완성도 타협 안 함','여백 많은 UI','정보 밀도 낮게']} />
      <Cluster className={styles.taste} name="TASTE" count="52" words={['파스텔 거부','다크 모드','디카페인']} />
      <Cluster className={styles.fadingCluster} name="FADING" count="31" words={['휴학 고민','B2C 창업']} />
      <svg className={styles.tensionLine} viewBox="0 0 310 70" aria-hidden="true"><path d="M4 48 C 86 12, 212 75, 306 18" /><circle cx="4" cy="48" r="3" /><circle cx="306" cy="18" r="3" /></svg><span className={styles.tensionTag}>팽팽함 · 조건 필요</span>
      <p className={styles.skyNote}>별의 크기는 그 기억이 답변에 실제로 쓰인 횟수입니다. 덩어리를 누르면 안쪽 기억이 펼쳐집니다.</p>
    </div>
    <aside className={styles.tensionPanel}><span className={screen.eyebrow}>선택한 충돌</span><h2>두 별이 서로를<br />밀어내고 있습니다</h2><div className={styles.tensionPair}><p>{tension.left}</p><GitBranch size={15} /><p>{tension.right}</p></div><span className={styles.ruleLabel}>AI가 본 규칙</span><div className={styles.rules}>{tension.rules.map((rule) => <div key={rule.context}><span>{rule.context}</span><i /><b>{rule.priority}</b></div>)}</div><div className={styles.tensionActions}>{tension.status === 'resolved' ? <span className={styles.resolved}><Check size={14} /> 조건 저장됨</span> : <><button className={screen.button} onClick={() => void resolveTension(tension.id, 'conditional')}>조건부 기억으로 분리</button><button className={screen.buttonGhost} onClick={() => void resolveTension(tension.id, 'keep-one')}>한쪽만 남기기</button></>}</div></aside>
  </div>
}

function Cluster({ className, name, count, words }: { className: string; name: string; count: string; words: string[] }) {
  return <div className={`${styles.cluster} ${className}`}><div className={styles.clusterHalo} />{words.map((word,index) => { const point = getClusterPoint(index); return <div key={word} className={styles.star} data-side={point.side} style={{ '--x': point.x, '--y': point.y, '--size': `${point.size}px` } as React.CSSProperties}><i /><span>{word}</span></div> })}<b>{name} · {count}</b></div>
}

function Manual() {
  const { workspace } = useMemory()
  const [open, setOpen] = useState('work-style')
  return <div className={styles.manualWrap}>
    <aside className={styles.marginNotes}><span>3주 전 고쳐 씀</span><p>“대체로”가<br />“거의 항상”으로</p><span className={styles.reviewNote}>검토 대기</span><p>이 문단은 8개월째<br />그대로입니다</p></aside>
    <article className={styles.manual}><header><h1>제가 지금 알고 있는 당신</h1><p>612개의 기억을 문장 아홉 개로 줄여 썼습니다. 틀린 문장을 눌러 고쳐 주세요.</p></header>{workspace.manual.map((section) => <section key={section.id} className={section.review ? styles.manualReview : ''}><button aria-label={`${section.eyebrow} 근거 보기`} onClick={() => setOpen(open === section.id ? '' : section.id)}><span>{section.eyebrow}</span><p>{section.text}</p>{section.review && <em>이 문단 다시 쓰기</em>}</button>{open === section.id && <div className={styles.manualEvidence}><span><Sparkles size={11} /> 이렇게 판단한 근거</span>{section.evidence.map((item) => <p key={item}>{item}</p>)}</div>}</section>)}</article>
  </div>
}

