:root {
  --bg: #08090b;
  --surface-0: #0b0c0f;
  --surface-1: #101216;
  --surface-2: #15181d;
  --surface-3: #1b1e24;
  --line: rgba(242, 239, 228, 0.1);
  --line-strong: rgba(242, 239, 228, 0.2);
  --text: #f2efe4;
  --text-soft: rgba(242, 239, 228, 0.68);
  --text-dim: rgba(242, 239, 228, 0.4);
  --paper: #f2efe4;
  --ink: #0b0c0f;
  --glass-surface: rgba(18, 20, 26, 0.58);
  --glass-surface-strong: rgba(24, 27, 34, 0.72);
  --glass-border: rgba(255, 255, 255, 0.14);
  --glass-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  --glass-shadow: 0 24px 64px rgba(0, 0, 0, 0.28);
  --ease: cubic-bezier(0.23, 1, 0.32, 1);
  color: var(--text);
