  font-family: 'Noto Sans KR', system-ui, sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }
html, body, #root { width: 100%; min-width: 1180px; min-height: 100%; margin: 0; }
body { min-height: 100vh; overflow: hidden; background: var(--bg); }
button, input { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid var(--paper); outline-offset: 3px; }
button { color: inherit; }
